(()=>{
 const $=id=>document.getElementById(id),svg=$('plan'),NS='http://www.w3.org/2000/svg';let state={...RoomEngine.defaults},layout,selected='bed',drag=null,view;
 try{const saved=JSON.parse(localStorage.getItem('abbie-bedroom-v1'));if(saved?.version===1)state=RoomEngine.normalize(saved);}catch{}
 const palettes={cozy:{floor:'#e8d9bf',wood:'#bca48b',bed:'#a19cb1',accent:'#cc9670',rug:'#d8be9e'},simple:{floor:'#e8e5dc',wood:'#b6b5ab',bed:'#97aaa9',accent:'#7e9c8d',rug:'#d4d9d4'},storybook:{floor:'#e6d5bf',wood:'#b69a85',bed:'#b39abc',accent:'#ce9c5f',rug:'#d1b5ca'}};
 function save(){try{localStorage.setItem('abbie-bedroom-v1',JSON.stringify(state));$('save-state').textContent='Saved on this device';}catch{$('save-state').textContent='Session only';}}
 function page(id){for(const p of document.querySelectorAll('.page'))p.hidden=p.id!==id;for(const b of document.querySelectorAll('nav button'))b.classList.toggle('active',b.dataset.page===id);if(id==='workspace')draw();}
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>page(b.dataset.page));$('three-next').onclick=()=>page('future');
 function node(tag,attrs={},parent=svg){const e=document.createElementNS(NS,tag);for(const[k,v]of Object.entries(attrs))e.setAttribute(k,v);parent.append(e);return e;}
 function label(text,x,y,attrs={},parent=svg){const t=node('text',{x,y,fill:'#786e7f','font-family':'DM Sans, sans-serif','font-size':10,'text-anchor':'middle',...attrs},parent);t.textContent=text;return t;}
 function draw(){layout=RoomEngine.generate(state);const W=svg.clientWidth||650,H=svg.clientHeight||470,pad=44,scale=Math.min((W-pad*2)/state.width,(H-pad*2)/state.depth),ox=(W-state.width*scale)/2,oy=(H-state.depth*scale)/2;view={scale,ox,oy};svg.setAttribute('viewBox',`0 0 ${W} ${H}`);svg.replaceChildren();node('title').textContent='A procedurally arranged bedroom';node('desc').textContent=layout.items.map(i=>i.name).join(', ')+'. '+(layout.checks.reachable?'All placed furniture has a route from the door.':'Layout needs more space.');const p=palettes[state.style],X=x=>ox+x*scale,Y=y=>oy+y*scale;
 node('rect',{x:ox-9,y:oy-9,width:state.width*scale+18,height:state.depth*scale+18,rx:3,fill:'#e5dde6'});node('rect',{x:ox,y:oy,width:state.width*scale,height:state.depth*scale,fill:p.floor});
 for(let i=.24;i<state.width;i+=.24)node('path',{d:`M ${X(i)} ${oy} V ${Y(state.depth)}`,stroke:'#7d675b','stroke-opacity':.09,'stroke-width':1});
 const bed=layout.items.find(i=>i.id==='bed');if(bed&&state.style!=='simple'){node('rect',{x:X(Math.max(.05,bed.x-.15)),y:Y(Math.max(.05,bed.y+.35)),width:Math.min(state.width-.1,bed.w+.3)*scale,height:Math.min(state.depth-bed.y-.1,bed.d+.35)*scale,rx:state.extras.includes('whimsy')?35:4,fill:p.rug,opacity:.65});}
 if(state.clearance)for(const it of layout.items)node('rect',{x:X(it.access.x),y:Y(it.access.y),width:it.access.w*scale,height:it.access.d*scale,fill:'#d7e5dc','fill-opacity':.25,stroke:'#8da695','stroke-opacity':.6,'stroke-width':1,'stroke-dasharray':'3 4'});
 const win=layout.window;node('rect',{x:X(win.x),y:oy-8,width:win.w*scale,height:13,fill:'#e9f5f4',stroke:'#a5bebd','stroke-width':2});node('line',{x1:X(win.x+win.w/2),y1:oy-8,x2:X(win.x+win.w/2),y2:oy+5,stroke:'#a5bebd'});label('DAYLIGHT',X(win.x+win.w/2),oy-19,{'font-size':8,'letter-spacing':1});
 for(const it of layout.items){const g=node('g',{class:'furn',role:'button',tabindex:0,'aria-label':it.name+' — '+it.reason,'data-id':it.id});g.onclick=()=>{selected=it.id;draw();};g.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selected=it.id;draw();}};const x=X(it.x),y=Y(it.y),w=it.w*scale,d=it.d*scale;node('rect',{x:x+2,y:y+3,width:w,height:d,rx:4,fill:'#584253',opacity:.12},g);node('rect',{x,y,width:w,height:d,rx:it.id==='chair'?12:4,fill:it.id==='bed'?p.bed:p.wood,stroke:selected===it.id?'#846093':'#8a778b','stroke-width':selected===it.id?2:1},g);
 if(it.id==='bed'){let tr=it.wall==='top'?`translate(${x} ${y})`:it.wall==='left'?`translate(${x} ${y+d}) rotate(-90)`:`translate(${x+w} ${y}) rotate(90)`;const bg=node('g',{transform:tr},g),bw=(it.wall==='top'?it.w:it.d)*scale,bd=2*scale;node('rect',{x:3,y:3,width:bw-6,height:.16*scale,rx:2,fill:'#76697e'},bg);const count=state.bed==='single'?1:2;for(let k=0;k<count;k++)node('rect',{x:5+k*(bw-10)/count,y:.22*scale,width:(bw-14)/count,height:.34*scale,rx:5,fill:'#f4eee6',stroke:'#dbd2d9'},bg);node('rect',{x:4,y:.7*scale,width:bw-8,height:bd-.76*scale,rx:3,fill:p.bed},bg);node('path',{d:`M 5 ${1.55*scale} H ${bw-5}`,stroke:'#e1d6e3','stroke-width':8},bg);
 }else if(it.id==='wardrobe'){node('line',{x1:x+w/2,y1:y+3,x2:x+w/2,y2:y+d-3,stroke:'#8e7b6b'},g);node('circle',{cx:x+w/2-4,cy:y+d/2,r:1.5,fill:'#5c4b59'},g);node('circle',{cx:x+w/2+4,cy:y+d/2,r:1.5,fill:'#5c4b59'},g);}else if(it.id==='desk'){node('rect',{x:x+w*.25,y:y+d*.2,width:w*.5,height:d*.5,rx:2,fill:'#eae5dc'},g);}else if(it.id==='chair'){node('rect',{x:x+5,y:y+7,width:w-10,height:d-12,rx:8,fill:p.bed},g);}
 label(it.id==='nightstand'?'':it.name,x+w/2,y+d/2+3,{'font-size':Math.max(8,Math.min(10,scale*.15)),fill:it.id==='bed'?'#44374d':'#554557','pointer-events':'none'},g);
 }
 for(const dec of layout.decor){if(dec.kind==='garland'){node('path',{d:`M ${X(.18)} ${Y(.23)} Q ${X(state.width/2)} ${Y(.7)} ${X(state.width-.18)} ${Y(.23)}`,fill:'none',stroke:'#94728e','stroke-width':1.5});for(let k=0;k<9;k++){const t=(k+.5)/9,xx=.18+t*(state.width-.36),yy=.23+.94*t*(1-t);node('path',{d:`M ${X(xx-.07)} ${Y(yy)} L ${X(xx+.07)} ${Y(yy)} L ${X(xx)} ${Y(yy+.18)} Z`,fill:k%2?p.accent:p.bed});}}else if(dec.kind==='stars'&&bed){for(let k=0;k<3;k++)label('✦',X(bed.x+bed.w*(.25+k*.25)),Y(bed.y+bed.d*.7),{fill:'#f5dda8','font-size':14});}else{const color=dec.kind==='plant'?'#719d84':dec.kind==='pumpkin'?'#d98c4a':dec.kind==='lamp'?'#f4d29a':p.accent;node('circle',{cx:X(dec.x),cy:Y(dec.y),r:dec.kind==='lamp'?6:4,fill:color,stroke:'#876c69','stroke-width':.5});}}
 // A persistent inward door swing is part of the placement constraints.
 const hinge=.18,doorW=.9;node('line',{x1:X(hinge),y1:Y(state.depth),x2:X(hinge+doorW),y2:Y(state.depth),stroke:'#fffdf9','stroke-width':12});node('path',{d:`M ${X(hinge)} ${Y(state.depth)} L ${X(hinge)} ${Y(state.depth-doorW)} A ${doorW*scale} ${doorW*scale} 0 0 1 ${X(hinge+doorW)} ${Y(state.depth)}`,fill:'none',stroke:'#9e849c','stroke-width':1.4});label('ENTRY',X(hinge+.45),Y(state.depth)+25,{'font-size':8,'letter-spacing':1});
 label(state.width.toFixed(1)+' m',X(state.width/2),Y(state.depth)+28);label(state.depth.toFixed(1)+' m',ox-27,Y(state.depth/2),{transform:`rotate(-90 ${ox-27} ${Y(state.depth/2)})`});
 for(const[cx,cy,sx,sy]of [[0,0,-1,-1],[state.width,0,1,-1],[state.width,state.depth,1,1],[0,state.depth,-1,1]]){const c=node('circle',{cx:X(cx),cy:Y(cy),r:7,fill:'#faf3fd',stroke:'#a689b1','stroke-width':2,class:'corner','data-sx':sx,'data-sy':sy});c.onpointerdown=e=>{e.preventDefault();drag={x:e.clientX,y:e.clientY,w:state.width,d:state.depth,sx,sy,scale};svg.setPointerCapture(e.pointerId);};}
 $('dimensions').textContent=(state.width*state.depth).toFixed(1)+' m²';$('width').value=state.width.toFixed(1);$('depth').value=state.depth.toFixed(1);$('bed-size').value=state.bed;$('density').value=state.density;$('density-value').textContent=state.density+'%';$('clearance').checked=state.clearance;
 for(const group of document.querySelectorAll('.pillset'))for(const b of group.querySelectorAll('button')){const val=state[group.dataset.group];b.setAttribute('aria-pressed',String(Array.isArray(val)?val.includes(b.dataset.value):val===b.dataset.value));}
 const sel=layout.items.find(i=>i.id===selected)||bed;if(sel){$('selected-title').textContent=sel.name;$('selected-reason').textContent=sel.reason;}else{$('selected-title').textContent='Give the bedroom more room';$('selected-reason').textContent='This bed and its access space cannot fit around the doorway. Try a single bed or drag a corner outward.';}
 $('layout-status').textContent=(layout.checks.reachable?'✓ Doorway clear · furniture reachable':'Room needs more space')+(layout.omitted.length?' · Not fitted: '+layout.omitted.join(', ')+'. Try a larger room or smaller bed.':'');
 }
 svg.onpointermove=e=>{if(!drag)return;state.width=Math.round(Math.max(2.8,Math.min(7,drag.w+(e.clientX-drag.x)/drag.scale*drag.sx))*10)/10;state.depth=Math.round(Math.max(2.8,Math.min(7,drag.d+(e.clientY-drag.y)/drag.scale*drag.sy))*10)/10;draw();};svg.onpointerup=()=>{drag=null;save();};svg.onpointercancel=()=>{drag=null;save();};
 for(const group of document.querySelectorAll('.pillset'))group.onclick=e=>{const b=e.target.closest('button');if(!b)return;const k=group.dataset.group,v=b.dataset.value;if(Array.isArray(state[k]))state[k]=state[k].includes(v)?state[k].filter(x=>x!==v):[...state[k],v];else state[k]=v;draw();save();};
 for(const [id,k]of [['width','width'],['depth','depth'],['density','density'],['bed-size','bed']])$(id).oninput=e=>{state[k]=k==='bed'?e.target.value:+e.target.value;state=RoomEngine.normalize(state);draw();save();};$('clearance').onchange=e=>{state.clearance=e.target.checked;draw();save();};$('variation').onclick=()=>{state.seed++;draw();save();};
 $('prompt-form').onsubmit=e=>{e.preventDefault();const text=$('prompt').value.toLowerCase();if(!/bedroom|bed room/.test(text)){$('prompt-note').textContent='Our first grammar is a bedroom. Try “cozy bedroom with a desk”.';return;}state={...RoomEngine.defaults,needs:[],extras:[],seed:state.seed};if(/small|tiny/.test(text)){state.width=3.2;state.depth=3.4;state.bed='single';}if(/large|spacious/.test(text)){state.width=5.5;state.depth=5;}if(/desk|work|study/.test(text))state.needs.push('desk');if(/read|book/.test(text))state.needs.push('reading');if(/storage|wardrobe/.test(text))state.needs.push('storage');if(/whims|magic/.test(text))state.extras.push('whimsy');if(/party|celebrat/.test(text))state.extras.push('party');if(/halloween|spooky/.test(text))state.motif='halloween';if(/plant|botanical/.test(text))state.motif='botanical';if(/storybook/.test(text))state.style='storybook';if(/simple|minimal|modern/.test(text))state.style='simple';$('prompt-note').textContent='Bedroom created from recognized directions. Refine it with the pills or room corners.';draw();save();};
 $('export').onclick=()=>{const result={schema:'abbies-world-room-v1',status:'2D prototype; 3D and real-asset fit pending',parameters:state,units:'meters',room:{width:state.width,depth:state.depth,height:2.6,door:layout.door,window:layout.window},furniture:layout.items.map(({score,...i})=>i),decoration:layout.decor,checks:layout.checks,omitted:layout.omitted,ruleBasis:'Explicit prototype heuristics; not learned or code-certified'};const u=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='abbies-bedroom-blueprint.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('toast').textContent='Bedroom blueprint exported.';};
 new ResizeObserver(()=>{if(!$('workspace').hidden)draw();}).observe(svg.parentElement);draw();
})();
